# limit BLAS threads (thread thrash made 10 s/turn on a loaded box)
def _limit_threads():
    import ctypes, glob as _gl, os as _os
    try:
        import numpy as _np
        d = _os.path.join(_os.path.dirname(_np.__file__), "..", "numpy.libs")
        for lib in _gl.glob(_os.path.join(d, "*openblas*")):
            L = ctypes.CDLL(lib)
            for fn in ("scipy_openblas_set_num_threads64_", "openblas_set_num_threads64_", "openblas_set_num_threads", "scipy_openblas_set_num_threads"):
                if hasattr(L, fn):
                    getattr(L, fn)(1)
    except Exception:
        pass
_limit_threads()
# ---------------- numpy runtime (generated by lab/bc/export.py) ----------------
import base64 as _b64, io as _io, zlib as _zlib
_W = dict(np.load(_io.BytesIO(_zlib.decompress(_b64.b85decode(_WBLOB)))))
_TEAM_VEC = np.zeros(len(_TEAMS), np.float32); _TEAM_VEC[_TEAMS.index(_TEAM)] = 1

def _conv(x, w, b):
    c, H, Wd = x.shape; o = w.shape[0]
    xp = np.pad(x, ((0, 0), (1, 1), (1, 1)))
    cols = np.stack([xp[:, i:i + H, j:j + Wd] for i in range(3) for j in range(3)], 1)  # c,9,H,W
    cols = cols.reshape(c * 9, H * Wd)
    return (w.reshape(o, c * 9) @ cols).reshape(o, H, Wd) + b[:, None, None]

def _relu(x): return np.maximum(x, 0)

def _forward(Bd, g, units):
    x = np.concatenate([Bd, np.broadcast_to(g[:, None, None], (len(g), 10, 10))], 0).astype(np.float32)
    h = _relu(_conv(x, _W["inp.weight"], _W["inp.bias"]))
    for k in range(_NBLOCKS):
        a = _relu(_conv(h, _W[f"body.{k}.a.weight"], _W[f"body.{k}.a.bias"]))
        h = _relu(h + _conv(a, _W[f"body.{k}.b.weight"], _W[f"body.{k}.b.bias"]))
    outs = []; tls = []; hf = h.reshape(h.shape[0], -1)
    for (ux, uy, uv) in units:
        z0 = np.concatenate([h[:, uy, ux], uv, g])
        z = _relu(_W["unit.0.weight"] @ z0 + _W["unit.0.bias"]); outs.append(_W["unit.2.weight"] @ z + _W["unit.2.bias"])
        if "tq.0.weight" in _W:
            q = _W["tq.2.weight"] @ _relu(_W["tq.0.weight"] @ z0 + _W["tq.0.bias"]) + _W["tq.2.bias"]
            tls.append(q @ hf / np.sqrt(h.shape[0]))
    pooled = np.concatenate([h.mean((1, 2)), h.max((1, 2)), g])
    m = _relu(_W["mkt.0.weight"] @ pooled + _W["mkt.0.bias"]); m = (_W["mkt.2.weight"] @ m + _W["mkt.2.bias"]).reshape(len(MKT_KEYS), MKT_MAX + 1)
    return outs, m, tls

_MOVES = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}

_SEED_COST = {"WHEAT": 10, "CARROT": 20, "TOMATO": 50, "STRAWBERRY": 100, "MELON": 80}
_ANIMAL_COST = {"GOOSE": 300, "COW": 400, "SHEEP": 500}
_LAND_COST = [1000, 2000, 4000]

def _fib(n):
    a, b = 1, 1
    for _ in range(n): a, b = b, a + b
    return a

_STRUCT = {"GOOSE": "COOP", "COW": "PASTURE", "SHEEP": "PASTURE"}
_MAX_HANDS = 16

def _tile_mask(obs, p, x, y, inv, day):
    """Mirror of policy.tile_masks (kaggriculture.py _apply_unit_action semantics); PLANT/PICKUP set later."""
    t = obs["farms"][p]["tiles"][y][x]; m = np.zeros(len(UNIT_OPS), bool); inv = inv or {}
    for mv, (dx, dy) in _MOVES.items():
        m[UNIT_IDX[mv]] = 0 <= x + dx < 10 and 0 <= y + dy < 10
    locked = t == "LOCKED"; empty = t is None
    d = t if isinstance(t, dict) else {}
    plant = d.get("kind") == "PLANT"; animal = "animal" in d
    if plant:
        age = day - int(d.get("planted_day", day)); fy = FIRST_YIELD.get(d.get("crop"), 99)
        m[UNIT_IDX["WATER"]] = not d.get("watered_today")
        m[UNIT_IDX["HARVEST"]] = age >= fy and int(d.get("yield_units", 0)) > 0
        m[UNIT_IDX["FERTILIZE"]] = inv.get("FERTILIZER", 0) > 0
    if animal:
        m[UNIT_IDX["HARVEST"]] = int(d.get("yield_units", 0)) > 0
        m[UNIT_IDX["FEED"]] = (not d.get("fed_today")) and inv.get("WHEAT", 0) > 0
        m[UNIT_IDX["CARE"]] = not d.get("cared_today")
        m[UNIT_IDX["COLLECT_FERTILIZER"]] = bool(d.get("fertilizer_available"))
    m[UNIT_IDX["BUILD_COOP"]] = m[UNIT_IDX["BUILD_PASTURE"]] = empty
    m[UNIT_IDX["DIG"]] = (not empty) and (not locked) and (not animal)
    adj = (x, y) in SHED_ADJ
    m[UNIT_IDX["DROP"]] = adj and sum(inv.values()) > 0
    for it in ITEMS:
        has = inv.get(it, 0) > 0
        if it in _STRUCT:
            m[UNIT_IDX["PLACE:" + it]] = has and ((d.get("kind") == _STRUCT[it] and not animal) or adj)
        else:
            m[UNIT_IDX["PLACE:" + it]] = has and adj
    m[UNIT_IDX["PASS"]] = True
    return m, (empty and not locked), adj

_PICK_N = {"FERTILIZER": 4}

def _unit_triple(k, inv, shed_left):
    if ":" not in k: return [k]
    op, it = k.split(":")
    if op == "PLANT": return ["PLANT", it]
    if op == "PICKUP":
        n = 1 if it in ANIMALS else _PICK_N.get(it, 3)
        n = max(1, min(n, int(shed_left.get(it, 0)))); shed_left[it] = shed_left.get(it, 0) - n
        return ["PICKUP", it, n]
    n = 1 if (it in ANIMALS or it == "FERTILIZER") else max(1, int((inv or {}).get(it, 1)))
    return ["PLACE", it, n]

_RNG = np.random.default_rng(_SEED)

def _pick(logits, mask=None):
    z = logits if mask is None else np.where(mask, logits, -1e9)
    if not _SAMPLE:
        return int(z.argmax())
    g = -np.log(-np.log(_RNG.random(z.shape) + 1e-20) + 1e-20)
    return int((z / _TEMP + g).argmax())

_MKT_ORDER_IDX = [MKT_IDX[k] for k in MKT_ORDER]

def _market(q):
    """Mirror of policy.build_market: fixed key order, HIRE/LAND/ANIMAL one per order (<=10), first 10 orders; no affordability filter."""
    out = []
    for k in _MKT_ORDER_IDX:
        key = MKT_KEYS[k]; n = int(q[k]); op, _, it = key.partition(":")
        if n <= 0: continue
        if op in ("HIRE", "BUY_LAND"):
            out += [[op]] * min(n, 10)
        elif op == "BUY_ANIMAL":
            out += [[op, it, 1]] * min(n, 10)
        else:
            out.append([op, it, n])
    return out[:10]

def agent(obs, config=None):
    try:
        p = int(obs.get("player", 0)); day = int(obs.get("day", int(obs.get("step", 0)) // 24))
        Bd = board_tensor(obs, p); g = np.concatenate([glob_vec(obs, p), _TEAM_VEC])
        ul = unit_list(obs, p); priv = obs.get("private") or {}
        outs, m, tls = _forward(Bd, g, ul)
        invs = priv.get("inventories") or []
        seeds_left = {c: int((priv.get("seeds") or {}).get(c, 0)) for c in CROPS}
        shed_left = {it: int((priv.get("shed") or {}).get(it, 0)) for it in ITEMS}
        tgts = [_pick(tls[i]) for i in range(len(ul))]
        acts = []
        for i, ((x, y, v), lg) in enumerate(zip(ul, outs)):
            inv = invs[i] if i < len(invs) else {}
            mu, empty_ok, adj = _tile_mask(obs, p, x, y, inv, day)
            for c in CROPS: mu[UNIT_IDX["PLANT:" + c]] = empty_ok and seeds_left[c] > 0
            for it in ITEMS: mu[UNIT_IDX["PICKUP:" + it]] = adj and shed_left[it] > 0
            tx, ty = tgts[i] % 10, tgts[i] // 10
            want = np.zeros(len(UNIT_OPS), bool)
            want[UNIT_IDX["EAST"]] = tx > x; want[UNIT_IDX["WEST"]] = tx < x; want[UNIT_IDX["SOUTH"]] = ty > y; want[UNIT_IDX["NORTH"]] = ty < y
            mv = want & mu
            if (tx, ty) != (x, y) and mv.any():
                mask = mv
            else:
                mask = mu.copy()
                for k in _MOVES: mask[UNIT_IDX[k]] = False
            k = UNIT_OPS[_pick(lg, mask)]
            if k.startswith("PLANT:"): seeds_left[k[6:]] -= 1
            acts.append(_unit_triple(k, inv, shed_left))
        farm = obs["farms"][p]
        hire_max = max(0, min(MKT_MAX, _MAX_HANDS - len(farm.get("hands") or [])))
        land_max = max(0, 3 - (len(farm.get("unlocked_quadrants") or []) - 1))
        b = np.arange(MKT_MAX + 1); remaining = 10; q = [0] * len(MKT_KEYS)
        for k in _MKT_ORDER_IDX:   # mirror of policy.sample_market (P0 fix): cap by remaining slots before sampling
            key = MKT_KEYS[k]; op = key.split(":")[0]
            if op in ("HIRE", "BUY_LAND", "BUY_ANIMAL"):
                cap = min(remaining, MKT_MAX)
                if op == "HIRE": cap = min(cap, hire_max)
                if op == "BUY_LAND": cap = min(cap, land_max)
            else:
                cap = MKT_MAX if remaining > 0 else 0
            q[k] = _pick(m[k], b <= cap)
            remaining -= q[k] if op in ("HIRE", "BUY_LAND", "BUY_ANIMAL") else int(q[k] > 0)
        return {"farmer": acts[0] if acts else ["PASS"], "hands": acts[1:], "market": _market(q)}
    except Exception:
        return {"farmer": ["PASS"], "hands": [], "market": []}
